#!/usr/bin/env node
// Global MD 200-line limit enforcer.
// PostToolUse hook: after any Write/Edit/MultiEdit on a .md file, check line count.
// If > 200, emit a <system-reminder> instructing Claude to split into companion files
// and reference them, or to WARN the user if a meaningful split is not possible.
// Exit 0 always — this is a soft advisory, not a block.

import { readFileSync, existsSync } from 'node:fs';
import { basename } from 'node:path';

const LIMIT = 200;

// Case-insensitive "stem prefix" exemptions — matches `<name>[.locale].md`.
// Covers documentation-purpose MDs created by developers: READMEs, SPECs,
// changelogs, licenses, and agent/memory/plan manifests.
const EXEMPT_STEM_PREFIXES_CI = new Set([
  'readme', 'spec', 'changelog', 'license', 'contributing',
  'notes', 'todo', 'faq', 'glossary',
  'claude', 'agents', 'memory',
]);

// Case-insensitive directory exemptions — if any path segment matches,
// the file is treated as a documentation artifact.
const EXEMPT_DIRS_CI = new Set([
  'docs', 'doc', 'documentation', 'spec', 'specs',
]);

// Inline opt-out marker (within first 500 chars of file).
const EXEMPT_MARKER = /<!--\s*md-line-limit:exempt\s*-->/i;

function readStdin() {
  try { return readFileSync(0, 'utf8'); } catch { return ''; }
}

function main() {
  const raw = readStdin();
  if (!raw.trim()) return;

  let payload;
  try { payload = JSON.parse(raw); } catch { return; }

  const tool = payload.tool_name;
  if (!['Write', 'Edit', 'MultiEdit'].includes(tool)) return;

  const filePath = payload.tool_input?.file_path;
  if (!filePath || !filePath.toLowerCase().endsWith('.md')) return;

  // Exempt by stem prefix — e.g., README.md, README.ko.md, SPEC.md, CLAUDE.md
  const stem = basename(filePath).toLowerCase().replace(/\.md$/, '');
  const firstSegment = stem.split('.')[0];
  if (EXEMPT_STEM_PREFIXES_CI.has(firstSegment)) return;

  // Exempt by parent directory:
  //   (a) anything under docs/, spec/, documentation/
  //   (b) anything under a dot-prefixed directory (.sc4sap/, .omc/, .github/, .claude/, ...)
